// Simple Asteroid Dodge game
// Canvas with id="game" must exist in the page

(function () {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas #game not found');
  const ctx = canvas.getContext('2d');

  // Set canvas size (fallback if not set in HTML)
  canvas.width = canvas.width || 400;
  canvas.height = canvas.height || 600;

  // Ship configuration
  const ship = {
    width: 40,
    height: 20,
    x: canvas.width / 2 - 20,
    y: canvas.height - 30,
    speed: 5,
    color: '#0ff',
  };

  // Input handling
  const keys = {};
  window.addEventListener('keydown', e => (keys[e.key] = true));
  window.addEventListener('keyup', e => (keys[e.key] = false));

  // Asteroid pool
  const asteroids = [];
  const asteroidSpawnInterval = 1000; // ms
  let lastAsteroidTime = 0;

  // Bullet pool (optional shooting)
  const bullets = [];
  const bulletSpeed = 7;

  function spawnAsteroid() {
    const size = Math.random() * 30 + 10;
    asteroids.push({
      x: Math.random() * (canvas.width - size),
      y: -size,
      size,
      speed: Math.random() * 2 + 1,
    });
  }

  function update(dt) {
    // Move ship
    if (keys['ArrowLeft']) ship.x -= ship.speed;
    if (keys['ArrowRight']) ship.x += ship.speed;
    // Keep within bounds
    ship.x = Math.max(0, Math.min(canvas.width - ship.width, ship.x));

    // Shoot with space
    if (keys[' '] && bullets.length < 5) {
      bullets.push({ x: ship.x + ship.width / 2, y: ship.y });
    }

    // Update bullets
    for (let i = bullets.length - 1; i >= 0; i--) {
      const b = bullets[i];
      b.y -= bulletSpeed;
      if (b.y < 0) bullets.splice(i, 1);
    }

    // Spawn asteroids
    if (Date.now() - lastAsteroidTime > asteroidSpawnInterval) {
      spawnAsteroid();
      lastAsteroidTime = Date.now();
    }

    // Update asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.y += a.speed;
      // Remove if off screen
      if (a.y > canvas.height) {
        asteroids.splice(i, 1);
        continue;
      }
      // Collision with ship (lose condition)
      if (
        a.x < ship.x + ship.width &&
        a.x + a.size > ship.x &&
        a.y < ship.y + ship.height &&
        a.y + a.size > ship.y
      ) {
        // Game over: stop loop
        cancelAnimationFrame(animId);
        ctx.fillStyle = 'red';
        ctx.font = '30px sans-serif';
        ctx.fillText('Game Over', canvas.width / 2 - 80, canvas.height / 2);
        return;
      }
      // Collision with bullets (destroy asteroid)
      for (let j = bullets.length - 1; j >= 0; j--) {
        const b = bullets[j];
        if (
          b.x > a.x &&
          b.x < a.x + a.size &&
          b.y > a.y &&
          b.y < a.y + a.size
        ) {
          asteroids.splice(i, 1);
          bullets.splice(j, 1);
          break;
        }
      }
    }
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    // Draw ship
    ctx.fillStyle = ship.color;
    ctx.fillRect(ship.x, ship.y, ship.width, ship.height);
    // Draw asteroids
    ctx.fillStyle = '#888';
    asteroids.forEach(a => {
      ctx.beginPath();
      ctx.arc(a.x + a.size / 2, a.y + a.size / 2, a.size / 2, 0, Math.PI * 2);
      ctx.fill();
    });
    // Draw bullets
    ctx.fillStyle = '#ff0';
    bullets.forEach(b => ctx.fillRect(b.x - 2, b.y - 5, 4, 10));
  }

  let lastTime = 0;
  let animId;
  function loop(timestamp) {
    const dt = timestamp - lastTime;
    lastTime = timestamp;
    update(dt);
    draw();
    animId = requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
